class Node
    public define value as integer;
    public define next as Node;
endClass

algorithm RunLinkedNode
    define v1 as integer;
    define v2 as integer;
    define first as Node;
    define second as Node;
    read v1;
    read v2;
    first <- new Node();
    second <- new Node();
    first.value <- v1;
    second.value <- v2;
    first.next <- second;
    write first.next.value;
endAlgorithm
